   $timers=$this->rows('SELECT id,actor_id,started_at,stopped_at,seconds FROM '.$this->prefix.'company_task_timers WHERE issuer_id=? AND task_id=? ORDER BY id LIMIT 501 FOR UPDATE',[$issuer,$t]);if(count($timers)>500)throw new DomainException('company_project_fixed_billing_limit');foreach($timers as &$timer){foreach(['id','actor_id','seconds'] as $k){if(!preg_match('/^(0|[1-9][0-9]{0,9})$/D',(string)$timer[$k]))throw new DomainException('company_project_fixed_billing_not_ready');$timer[$k]=(int)$timer[$k];}foreach(['started_at','stopped_at'] as $field){$v=$timer[$field];$d=is_string($v)?DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v):false;if(!$d||$d->format('Y-m-d H:i:s')!==$v)throw new DomainException('company_project_fixed_billing_not_ready');}if($timer['stopped_at']<$timer['started_at']||$timer['seconds']>4294967295)throw new DomainException('company_project_fixed_billing_not_ready');}unset($timer);
   $portal=$this->portal($issuer,$t);if($portal){if((int)$portal['project_id']!==$id||(int)$portal['client_id']!==$p['client_id']||$portal['billing_state']!==$portalState)throw new DomainException('company_project_fixed_billing_overlap');foreach(['issuer_id','project_id','task_id','client_id','contact_id'] as $k)$portal[$k]=(int)$portal[$k];unset($portal['billing_state']);}$item=['task'=>$task,'timers'=>$timers,'portal_origin'=>$portal];$bytes+=strlen(self::encode($item))+1;if($bytes>2097152)throw new DomainException('company_project_fixed_billing_limit');$captured[]=$item;
  }
  if($keys&&$this->rows('SELECT request_key FROM '.$this->prefix.'company_invoice_requests WHERE request_key IN('.implode(',',array_fill(0,count($keys),'?')).') FOR UPDATE',$keys))throw new DomainException('company_project_fixed_billing_overlap');$source=['basis'=>'project_fixed_completed_v1','project'=>$p,'tasks'=>$captured,'timer_timestamp_basis'=>'native_server_local_naive_duration_seconds_authoritative'];if(strlen(self::encode($source))>2097152)throw new DomainException('company_project_fixed_billing_limit');return $source;
